require_once __DIR__.'/../lib/helpers.php';send_cors_headers();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$token=trim((string)($body['token']??''));$password=(string)($body['password']??'');$confirmation=(string)($body['password_confirmation']??'');if(strlen($token)<40||!is_strong_enough_password($password)||$password!==$confirmation)json_response(422,['success'=>false,'message'=>'Reset token or new password is invalid.']);$db=get_db();$db->beginTransaction();try{$stmt=$db->prepare('SELECT * FROM password_reset_tokens WHERE token_hash=:hash AND used_at IS NULL AND expires_at>UTC_TIMESTAMP() FOR UPDATE');$stmt->execute(['hash'=>hash_hmac('sha256',$token,APP_KEY)]);$reset=$stmt->fetch();if(!$reset)json_response(410,['success'=>false,'message'=>'Reset link is invalid or expired.']);$table=['customer'=>'users','vendor'=>'vendors','influencer'=>'influencers'][$reset['principal_type']]??null;if(!$table)json_response(400,['success'=>false,'message'=>'Reset link is invalid.']);$db->prepare("UPDATE {$table} SET password_hash=:hash,updated_at=UTC_TIMESTAMP() WHERE id=:id")->execute(['hash'=>password_hash($password,PASSWORD_DEFAULT),'id'=>$reset['principal_id']]);$db->prepare('UPDATE password_reset_tokens SET used_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$reset['id']]);revoke_principal_sessions($reset['principal_type'],$reset['principal_id'],'password_reset');audit_event($reset['principal_type'].'.password_reset',$reset['principal_type'],$reset['principal_id'],[],['type'=>$reset['principal_type'],'id'=>$reset['principal_id']]);$db->commit();json_response(200,['success'=>true,'message'=>'Password changed. Sign in with your new password.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
